// @ts-nocheck
// ===== อ่านค่า D210 (ลองหา PRODUCTION NAME) จาก PLC Omron NJ ด้วย FINS UDP (อ่านอย่างเดียว) =====
// ส่งออกเฉพาะเมื่อค่าเปลี่ยน -> คีย์ค่าใหม่บนจอ HMI + ENT แล้วดู debug ได้ทันที
// msg.payload = "all" -> อ่านทุกจุดที่เคยเจอ "CG" (D110, D210, D1000, D1012, D1236) ส่งออกทุกครั้ง
const HOST = "192.168.250.1", DA1 = 1, SA1 = 50;   // SA1 = เลขท้าย IP กล่อง (192.168.250.50)
const LEN = 5;                                     // อ่าน 5 word = 10 ตัวอักษร
const MAIN = 210;                                  // <- D ที่ต้องการอ่าน (แก้เลขนี้ได้ เช่น 110, 1000, 1012)
const ADDRS = msg.payload === "all" ? [110, 210, 1000, 1012, 1236] : [MAIN];

let S = context.get("S");
if (!S) {
    const sock = dgram.createSocket("udp4");
    S = { sock, pending: null, sid: 0 };
    sock.on("message", r => { if (S.pending && r.length >= 14 && r[9] === S.sid) S.pending(null, r); });
    sock.on("error", e => S.pending && S.pending("socket " + e.code));
    sock.bind(0);
    context.set("S", S);
}
if (S.busy) return null;
S.busy = true;

function read(start, count) {
    return new Promise(res => {
        S.sid = (S.sid + 1) & 0xFF;
        const t = setTimeout(() => S.pending && S.pending("timeout"), 800);
        S.pending = (err, r) => {
            clearTimeout(t); S.pending = null;
            if (err) return res({ err });
            const ec = r.readUInt16BE(12);
            if (ec !== 0 && ec !== 0x0040) return res({ err: "end code 0x" + ec.toString(16) });
            const w = []; for (let k = 0; k < count; k++) w.push(r.readUInt16BE(14 + k * 2));
            res({ w });
        };
        S.sock.send(Buffer.from([0x80, 0, 0x02, 0, DA1, 0, 0, SA1, 0, S.sid, 0x01, 0x01, 0x82,
            (start >> 8) & 0xFF, start & 0xFF, 0, (count >> 8) & 0xFF, count & 0xFF]), 9600, HOST,
            e => { if (e && S.pending) S.pending("send " + e.code); });
    });
}
const ch = c => (c >= 32 && c < 127 ? String.fromCharCode(c) : "");
const nj = w => w.map(v => ch(v & 0xFF) + ch((v >> 8) & 0xFF)).join("").trim();   // NJ (สลับ byte)
const nm = w => w.map(v => ch((v >> 8) & 0xFF) + ch(v & 0xFF)).join("").trim();   // ปกติ

(async () => {
    const out = {};
    for (const a of ADDRS) {
        const r = await read(a, LEN);
        if (r.err) { out["D" + a] = { error: r.err }; continue; }
        out["D" + a] = {
            "ข้อความ (NJ)": nj(r.w),
            "ข้อความ (ปกติ)": nm(r.w),
            "เลข (word แรก)": r.w[0],
            "ค่าดิบ": r.w.map((v, i) => "D" + (a + i) + "=" + v + " (0x" + v.toString(16).padStart(4, "0") + ")")
        };
    }
    S.busy = false;
    const d = out["D" + MAIN];
    node.status(d && !d.error ? { fill: "green", shape: "dot", text: "D" + MAIN + " = \"" + d["ข้อความ (NJ)"] + "\"  (word=" + d["เลข (word แรก)"] + ")" }
                              : { fill: "red", shape: "ring", text: "D" + MAIN + ": " + (d ? d.error : "-") });
    const key = JSON.stringify(out);
    if (msg.payload !== "all" && context.get("last") === key) return;   // ค่าเดิม ไม่ส่งซ้ำ
    context.set("last", key);
    node.send({ payload: Object.assign({ time: new Date().toLocaleTimeString("th-TH") }, out) });
})();
return null;
